// SectionSearchIndex — local Quartz emitter plugin.
//
// Wraps the stock `@quartz-community/content-index` emitter: sitemap.xml, RSS and
// the page-level `static/contentIndex.json` are generated by the stock code, then
// this plugin rewrites `contentIndex.json` so each page is split into one entry
// per section:
//
//   - one entry per rendered heading (`h1`–`h4` with an `id`; deeper headings
//     stay merged in their parent section, below the TOC maxDepth), keyed
//     `pageslug#heading-id`, titled with the heading text and carrying a
//     parent-path for the search preview line.
//     (No whole-page lead entry: only sections are searchable.)
//
// Search is intentionally TITLE-ONLY (parent path + title in the `content`
// field) so word-in-body queries return empty instead of the whole page.
// Heading ids are read from the rendered hast tree (same ids the
// TableOfContents transformer slugifies), and any id not present in the page
// TOC is warned at build time.
import { readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { ContentIndex } from "@quartz-community/content-index";
const HEADING_TAG = /^h[1-6]$/;
// TOC parity: quartz.config.yaml `filters.toc.maxDepth: 4` — the TOC slugger only
// emits h1–h4 anchors, so deeper headings stay merged in their parent section
// instead of becoming unlinked search entries.
const TOC_MAX_DEPTH = 4;
function innerText(node) {
    if (node == null)
        return "";
    if (node.type === "text")
        return node.value ?? "";
    if (Array.isArray(node.children))
        return node.children.map(innerText).join("");
    return "";
}
function collectTocSlugs(entries, out) {
    for (const entry of entries ?? []) {
        if (entry.slug)
            out.add(entry.slug);
        collectTocSlugs(entry.children, out);
    }
    return out;
}
function splitPage(pageSlug, pageEntry, tree, tocSlugs) {
    const sections = [];
    // Stack tracks heading hierarchy for parent-path (level ascending).
    const stack = [];
    let current = {
        title: pageEntry.title,
        anchor: null,
        parentPath: "",
        chunks: [],
    };
    const flush = () => {
        if (current.anchor === null)
            return; // no whole-page entry: only sections are searchable
        if (current.title.length === 0)
            return;
        const key = `${pageSlug}#${current.anchor}`;
        // TITLE-ONLY search: content = parentPath + title (body NOT indexed).
        // Parent path shown as preview line under title in stock search UI.
        const searchableContent = current.parentPath
            ? `${current.parentPath} ${current.title}`.trim()
            : current.title;
        sections.push({
            key,
            title: current.title,
            links: pageEntry.links ?? [],
            tags: pageEntry.tags ?? [],
            content: searchableContent,
        });
    };
    const visit = (node) => {
        if (node == null)
            return;
        if (node.type === "text") {
            const text = (node.value ?? "").replace(/\s+/g, " ").trim();
            if (text)
                current.chunks.push(text);
            return;
        }
        if (node.type !== "element") {
            if (Array.isArray(node.children))
                node.children.forEach(visit);
            return;
        }
        const tagName = node.tagName ?? "";
        if (HEADING_TAG.test(tagName)) {
            const id = node.properties?.id;
            const title = innerText(node).replace(/\s+/g, " ").trim();
            const level = parseInt(tagName[1], 10);
            if (typeof id === "string" &&
                id.length > 0 &&
                title.length > 0 &&
                level <= TOC_MAX_DEPTH) {
                if (tocSlugs && !tocSlugs.has(id)) {
                    console.warn(`[SectionSearchIndex] heading id "${id}" on page "${pageSlug}" is missing from the TOC — search anchor may not match the TOC anchor.`);
                }
                flush();
                // Pop until parent level < current
                while (stack.length > 0 && stack[stack.length - 1].level >= level)
                    stack.pop();
                const parentPath = stack.map((s) => s.title).join(" › ");
                stack.push({ level, title });
                current = { title, anchor: id, parentPath, chunks: [] };
                return;
            }
            if (title)
                current.chunks.push(title);
            return;
        }
        if (Array.isArray(node.children))
            node.children.forEach(visit);
    };
    if (Array.isArray(tree?.children))
        tree.children.forEach(visit);
    flush();
    return sections;
}
export default function SectionSearchIndex(opts) {
    const stock = ContentIndex(opts);
    async function rewrite(ctx, content) {
        const indexPath = join(ctx.argv.output, "static", "contentIndex.json");
        const raw = await readFile(indexPath, "utf-8");
        const pageIndex = JSON.parse(raw);
        const treesBySlug = new Map();
        const tocBySlug = new Map();
        for (const [tree, file] of content) {
            const slug = file?.data?.slug;
            if (typeof slug !== "string")
                continue;
            treesBySlug.set(slug, tree);
            tocBySlug.set(slug, collectTocSlugs(file?.data?.toc, new Set()));
        }
        const sectionIndex = {};
        for (const [pageSlug, pageEntry] of Object.entries(pageIndex)) {
            const tree = treesBySlug.get(pageSlug);
            if (!tree) {
                sectionIndex[pageSlug] = pageEntry;
                continue;
            }
            for (const section of splitPage(pageSlug, pageEntry, tree, tocBySlug.get(pageSlug))) {
                sectionIndex[section.key] = {
                    title: section.title,
                    content: section.content,
                    links: section.links,
                    tags: section.tags,
                };
            }
        }
        await writeFile(indexPath, JSON.stringify(sectionIndex));
    }
    return {
        name: "SectionSearchIndex",
        async emit(ctx, content, resources) {
            const outputs = await stock.emit(ctx, content, resources);
            await rewrite(ctx, content);
            return outputs;
        },
        async partialEmit(ctx, content, resources) {
            const outputs = stock.partialEmit
                ? await stock.partialEmit(ctx, content, resources)
                : await stock.emit(ctx, content, resources);
            await rewrite(ctx, content);
            return outputs;
        },
    };
}
